import 'dart:math';

/// The alphabet a room code is drawn from.
///
/// No `I`, `O`, `0` or `1`. A code is read aloud across a table and typed by
/// hand when a camera fails, and those four characters are the ones people
/// mistype for each other. 32 characters over six places is ~1.07 billion
/// codes, which is more than enough for rooms that live for one evening.
const String kRoomCodeAlphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';

/// Six characters, matching the code the board prints.
const int kRoomCodeLength = 6;

/// A room code: generated by the board, typed or scanned by a phone.
///
/// The code names a room, it is not a secret and not a password. It exists so a
/// phone that found *a* board can be sure it found *the* board it was told
/// about, and so a player can join without reading an IP address aloud.
abstract final class RoomCode {
  static final Random _secure = Random.secure();

  /// A fresh code. [random] is for tests that need a fixed sequence.
  static String generate([Random? random]) {
    final source = random ?? _secure;
    final buffer = StringBuffer();
    for (var i = 0; i < kRoomCodeLength; i++) {
      buffer.write(kRoomCodeAlphabet[source.nextInt(kRoomCodeAlphabet.length)]);
    }
    return buffer.toString();
  }

  /// The code as the player meant it, or null when it cannot be one.
  ///
  /// Uppercases and drops spaces and hyphens, so `7k3 qf9` and `7K3-QF9` are
  /// both `7K3QF9`. Anything else — a wrong length, a character outside the
  /// alphabet — is rejected rather than guessed at, because guessing here means
  /// connecting to the wrong board.
  static String? normalise(String input) {
    final cleaned = input.toUpperCase().replaceAll(RegExp(r'[\s-]'), '');
    if (cleaned.length != kRoomCodeLength) return null;
    for (var i = 0; i < cleaned.length; i++) {
      if (!kRoomCodeAlphabet.contains(cleaned[i])) return null;
    }
    return cleaned;
  }

  static bool isValid(String input) => normalise(input) != null;

  /// `7K3QF9` → `7K3 QF9`, so the two halves can be read off the board.
  static String grouped(String code) {
    if (code.length != kRoomCodeLength) return code;
    return '${code.substring(0, 3)} ${code.substring(3)}';
  }
}
